# Readings by interest, Valencian (AVL forms). Same format as interests_es.py
R = [
 ('lectura_ca_l1_lluna', 1, 'La Lluna', '🌙', ['espacio'],
  'Per la nit mire el cel. Veig la Lluna. A vegades és redona i gran. Altres vegades pareix un somriure. La Lluna no té llum pròpia. Brilla perquè li arriba la llum del Sol.',
  [('Quan mira el cel?', ['Pel matí', 'Per la vesprada', 'Per la nit'], 2, '«Per la nit mire el cel.»'),
   ('Què pareix la Lluna a vegades?', ['Una estrela', 'Un somriure', 'Un quadrat'], 1, '«Altres vegades pareix un somriure.»'),
   ('Per què brilla la Lluna?', ["Perquè té llum pròpia de nit", "Perquè li arriba la llum del Sol", "Perquè és feta de foc i de pedra"], 1, '«Brilla perquè li arriba la llum del Sol.»')]),
 ('lectura_ca_l2_basquet', 2, 'El partit de Sara', '🏀', ['deporte'],
  'Sara juga a bàsquet en l’equip del barri. Dissabte tenen un partit important. Al principi, Sara falla tres tirs i es posa trista. El seu entrenador li diu: «No passa res, continua intentant-ho». En l’últim minut, Sara llança la pilota des de lluny. Cistella! El seu equip guanya per dos punts i tots l’abracen.',
  [('A què juga Sara?', ['A futbol', 'A bàsquet', 'A tenis'], 1, '«Sara juga a bàsquet.»'),
   ('Què li diu l’entrenador?', ['Que descanse', 'Que continue intentant-ho', 'Que se’n vaja a casa'], 1, '«No passa res, continua intentant-ho.»'),
   ('Per quants punts guanya el seu equip?', ['Per un', 'Per dos', 'Per deu'], 1, '«El seu equip guanya per dos punts.»')]),
 ('lectura_ca_l2_colors', 2, 'Mescle colors', '🎨', ['arte', 'ciencia'],
  'Hui, en classe de plàstica, pintem amb tèmperes. La mestra ens porta tres colors: roig, blau i groc. Si mescle blau i groc, ix verd. Si mescle roig i groc, ix taronja. I amb roig i blau, ix morat! Amb només tres colors puc pintar un arc de Sant Martí sencer.',
  [('Amb què pinten?', ['Amb llapis', 'Amb tèmperes', 'Amb ceres'], 1, '«Pintem amb tèmperes.»'),
   ('Quin color ix si mesclem blau i groc?', ['Verd', 'Taronja', 'Morat'], 0, '«Si mescle blau i groc, ix verd.»'),
   ('Què ix amb roig i blau?', ['Marró', 'Verd', 'Morat'], 2, '«I amb roig i blau, ix morat!»')]),
 ('lectura_ca_l3_planetes', 3, 'El nostre veïnat: el sistema solar', '🪐', ['espacio', 'ciencia'],
  'La Terra no està sola en l’espai. Forma part del sistema solar, que té en el centre una estrela: el Sol. Al voltant del Sol giren huit planetes. El més pròxim és Mercuri, i el més llunyà, Neptú.\n\nCada planeta és molt diferent. Júpiter és el més gran de tots: dins d’ell hi cabrien més de mil planetes com el nostre. Mart es veu rogenc perquè el seu sòl té molt d’òxid de ferro. I la Terra és l’únic planeta on sabem que hi ha vida.',
  [('Què hi ha en el centre del sistema solar?', ['La Terra', 'El Sol', 'La Lluna'], 1, '«Té en el centre una estrela: el Sol.»'),
   ('Quin és el planeta més gran?', ['Mart', 'Neptú', 'Júpiter'], 2, '«Júpiter és el més gran de tots.»'),
   ('Per què Mart es veu rogenc?', ["Perquè allí sempre fa moltíssima calor", "Perquè el seu sòl té molt d’òxid de ferro", "Perquè està més prop del Sol que la Terra"], 1, '«El seu sòl té molt d’òxid de ferro.»')]),
 ('lectura_ca_l3_orquestra', 3, 'Els instruments de l’orquestra', '🎻', ['arte'],
  'En una orquestra toquen molts músics alhora, i cadascun té el seu instrument. Els instruments s’agrupen en famílies.\n\nLa família de corda té violins, violes, violoncels i contrabaixos: sonen quan es freguen les cordes amb un arc. La família de vent inclou flautes, clarinets i trompetes: sonen quan s’hi bufa. La percussió, amb tambors i plats, sona quan la colpeges. Davant de tots està el director, que marca el ritme amb una batuta.',
  [('Com s’agrupen els instruments?', ['Per colors', 'En famílies', 'Per grandàries'], 1, '«Els instruments s’agrupen en famílies.»'),
   ('Com sonen els instruments de vent?', ['Quan els colpeges', 'Quan s’hi bufa', 'Quan es freguen les cordes'], 1, '«Sonen quan s’hi bufa.»'),
   ('Què fa servir el director per a marcar el ritme?', ['Una batuta', 'Un tambor', 'Una flauta'], 0, '«Marca el ritme amb una batuta.»')]),
 ('lectura_ca_l4_paralimpics', 4, 'Els Jocs Paralímpics', '🏅', ['deporte', 'historia'],
  'Cada quatre anys, després dels Jocs Olímpics, se celebren els Jocs Paralímpics. Hi competixen esportistes amb alguna discapacitat física, visual o intel·lectual.\n\nEls primers es van celebrar a Roma l’any 1960. El seu origen està en un hospital d’Anglaterra, on un metge, Ludwig Guttmann, utilitzava l’esport per a ajudar els soldats ferits en la guerra a recuperar-se.\n\nHui hi ha esports com el bàsquet en cadira de rodes, la natació o el goalball, un joc per a persones cegues o amb poca visió en què la pilota porta cascavells. Els atletes paralímpics demostren que el talent i l’esforç no tenen límits.',
  [('Quan se celebren els Jocs Paralímpics?', ['Abans dels Jocs Olímpics', 'Després dels Jocs Olímpics', 'Cada any'], 1, '«Després dels Jocs Olímpics, se celebren els Jocs Paralímpics.»'),
   ('On es van celebrar els primers?', ['A Londres', 'A Roma', 'A Madrid'], 1, '«Els primers es van celebrar a Roma l’any 1960.»'),
   ('Què té d’especial la pilota del goalball?', ['És molt gran', 'Porta cascavells', 'És de fusta'], 1, '«La pilota porta cascavells.»')]),
 ('lectura_ca_l5_estacio', 5, 'Una casa en l’espai', '🛰️', ['espacio', 'tecnologia'],
  'A uns 400 quilòmetres damunt dels nostres caps, una enorme nau fa voltes al voltant de la Terra: l’Estació Espacial Internacional. Des de l’any 2000 sempre hi ha astronautes vivint-hi. La van construir entre diversos països, peça a peça, com un joc de construcció gegant.\n\nL’estació va tan ràpida que fa una volta completa a la Terra en uns noranta minuts. Per això, els astronautes veuen unes setze albades cada dia. Allà tot sura: dormen en sacs lligats a la paret, beuen amb canyetes de bosses tancades i fan unes dues hores d’exercici diari perquè els músculs i els ossos no es debiliten.\n\nEn l’estació es fan experiments que serien impossibles en la Terra.',
  [('Des de quan sempre hi ha astronautes en l’estació?', ['Des de 1969', 'Des de l’any 2000', 'Des de l’any passat'], 1, '«Des de l’any 2000 sempre hi ha astronautes vivint-hi.»'),
   ('Quant tarda a fer una volta a la Terra?', ["Un dia sencer", "Uns noranta minuts", "Una setmana i mitja"], 1, '«Fa una volta completa a la Terra en uns noranta minuts.»'),
   ('Per què fan exercici els astronautes?', ["Per a no avorrir-se durant els viatges llargs", "Perquè els músculs i els ossos no es debiliten", "Per a guanyar una cursa contra una altra nau"], 1, '«Perquè els músculs i els ossos no es debiliten.»')]),
 ('lectura_ca_l5_sorolla', 5, 'Sorolla, el pintor de la llum', '🖼️', ['arte', 'historia'],
  'Joaquim Sorolla va nàixer a València l’any 1863. Des de xicotet li encantava dibuixar, i amb els anys es va convertir en un dels pintors espanyols més famosos de la seua època.\n\nA Sorolla l’anomenen «el pintor de la llum». Li agradava pintar a l’aire lliure, sobretot a les platges de València: xiquets banyant-se, pescadors, barques i veles blanques mogudes pel vent. Pintava de pressa, amb pinzellades soltes, per a atrapar la llum del sol abans que canviara.\n\nHui es poden veure molts dels seus quadres en el Museu Sorolla de Madrid, que va ser la seua casa. Quan els mires, pareix que se sent la mar i la calor de l’estiu.',
  [('On va nàixer Sorolla?', ['A Madrid', 'A València', 'A Sevilla'], 1, '«Joaquim Sorolla va nàixer a València l’any 1863.»'),
   ('Per què pintava de pressa?', ['Perquè tenia pressa per a dinar', 'Per a atrapar la llum abans que canviara', 'Perquè no li agradava pintar'], 1, '«Per a atrapar la llum del sol abans que canviara.»'),
   ('Què va ser abans el Museu Sorolla?', ['Una escola', 'La seua casa', 'Una platja'], 1, '«El Museu Sorolla de Madrid, que va ser la seua casa.»')]),
 ('lectura_ca_l6_dormir', 6, 'Dormir també és entrenar', '😴', ['deporte', 'ciencia', 'vida'],
  'Molts esportistes d’elit tenen una cosa en comú que no es veu en les competicions: es prenen el son molt seriosament. Saben que mentre dormim el cos repara els músculs, recupera l’energia i fixa el que hem après durant el dia, ja siga un moviment nou o la lliçó de matemàtiques.\n\nEls especialistes recomanen que els adolescents dormen entre huit i deu hores cada nit. No obstant això, molts no hi arriben. Una de les causes són les pantalles: la llum del mòbil a la nit enganya el cervell, que retarda la sensació de son, i els missatges i els vídeos ens mantenen desperts «només cinc minuts més».\n\nDormir poc té conseqüències. Costa concentrar-se, ens enfadem més fàcilment, rendim pitjor en l’esport i augmenta el risc de lesions.\n\nAlguns consells senzills ajuden: gitar-se i alçar-se a la mateixa hora, deixar el mòbil fora del dormitori i no fer exercici intens just abans d’anar a dormir. Dormir bé no és perdre el temps: és una part més de l’entrenament.',
  [('Segons el text, què fa el cos mentre dormim?', ['Només descansa la vista', 'Repara els músculs i fixa el que hem après', 'Crema tot el menjar', 'El cervell deixa de funcionar'], 1, '«El cos repara els músculs, recupera l’energia i fixa el que hem après.»'),
   ('Quantes hores es recomana que dormen els adolescents?', ['Entre cinc i sis', 'Entre sis i set', 'Entre huit i deu', 'Dotze o més'], 2, '«Entre huit i deu hores cada nit.»'),
   ('Per què la llum del mòbil dificulta adormir-se?', ['Perquè fa soroll', 'Perquè enganya el cervell i retarda la son', 'Perquè escalfa l’habitació', 'Perquè gasta bateria'], 1, '«Enganya el cervell, que retarda la sensació de son.»'),
   ('Quina d’estes NO és una conseqüència de dormir poc, segons el text?', ['Costa concentrar-se', 'Augmenta el risc de lesions', 'Es creix més de pressa', 'Rendim pitjor en l’esport'], 2, 'El text no diu res sobre créixer més de pressa.'),
   ('Què vol dir la frase final?', ['Que dormir és avorrit', 'Que el descans forma part de la preparació', 'Que cal entrenar de nit', 'Que els esportistes dormen poc'], 1, '«És una part més de l’entrenament.»')]),
 ('lectura_ca_l7_mart', 7, 'Hi va haver aigua a Mart?', '🔴', ['espacio', 'ciencia'],
  'Vist des de la Terra, Mart és un punt rogenc en el cel. De prop, és un desert gelat i polsós, amb una atmosfera tan fina que no hi podríem respirar. I, tanmateix, els científics estan convençuts que fa milers de milions d’anys per la seua superfície corrien rius i hi havia llacs.\n\nCom ho saben? Les fotografies preses per satèl·lits mostren llits de rius secs, deltes i roques que només es formen en presència d’aigua. A més, en els pols de Mart hi ha casquets de gel, i davall del sòl també se n’ha detectat.\n\nL’aigua líquida no pot romandre molt de temps en la superfície actual: la pressió és tan baixa que s’evaporaria o es gelaria de seguida. Per això, els robots exploradors busquen pistes del passat. El rover Perseverance va aterrar l’any 2021 en el cràter Jezero, on hi va haver un llac, per a arreplegar mostres de roca que, en el futur, es podrien portar a la Terra.\n\nLa gran pregunta continua oberta: si Mart va tindre aigua, va arribar a tindre vida? Trobar la resposta podria canviar el que sabem sobre el nostre lloc en l’univers.',
  [('Com és hui la superfície de Mart?', ['Un oceà calent', 'Un desert gelat i polsós', 'Una selva humida', 'Una plana coberta d’herba'], 1, '«És un desert gelat i polsós.»'),
   ('Quines proves indiquen que hi va haver aigua?', ['Que Mart es veu roig', 'Llits de rius secs, deltes i roques que es formen amb aigua', 'Que té una atmosfera fina', 'Que està lluny del Sol'], 1, '«Llits de rius secs, deltes i roques que només es formen en presència d’aigua.»'),
   ('Per què no hi pot haver aigua líquida molt de temps en la superfície?', ['Perquè hi ha massa robots', 'Perquè la pressió és molt baixa', 'Perquè hi ha massa oxigen', 'Perquè mai no fa vent'], 1, '«La pressió és tan baixa que s’evaporaria o es gelaria de seguida.»'),
   ('Per a què va anar Perseverance al cràter Jezero?', ['Per a buscar or', 'Per a construir una base', 'Per a arreplegar mostres de roca on hi va haver un llac', 'Per a fer fotos de la Terra'], 2, '«Per a arreplegar mostres de roca.»'),
   ('Quina és «la gran pregunta» del final?', ['Si Mart és roig', 'Si Mart va arribar a tindre vida', 'Quan arribarà el pròxim robot', 'Si hi ha gel en els pols'], 1, '«Si Mart va tindre aigua, va arribar a tindre vida?»')]),
 ('lectura_ca_l8_ia', 8, 'Pensen les màquines?', '🤖', ['tecnologia'],
  'Hui parlem amb assistents de veu, rebem recomanacions de vídeos i traduïm textos en segons gràcies a la intel·ligència artificial (IA). Alguns programes escriuen redaccions o creen imatges a partir d’una frase. Davant de resultats tan sorprenents, és fàcil preguntar-se si estes màquines pensen com nosaltres.\n\nLa resposta de la majoria dels experts és més prudent. Estos sistemes aprenen analitzant quantitats enormes de dades i detecten patrons: quina paraula sol anar després d’una altra o quina forma té un gat en milers de fotos. Gràcies a això poden donar respostes molt convincents, però no tenen experiències ni una comprensió del món com la humana. I a vegades s’equivoquen amb tota seguretat.\n\nPer això convé utilitzar-los amb esperit crític. Una IA ens pot ajudar a organitzar idees o a repassar, però si li deixem fer tot el treball, no aprenem. A més, cal comprovar la informació que ens proporciona, igual que faríem amb qualsevol pàgina d’internet.\n\nLa intel·ligència artificial és una eina poderosa. Que ens faça millors o més ganduls dependrà, en gran part, de com decidim utilitzar-la.',
  [('Segons el text, com aprenen estos sistemes?', ['Llegint la ment de les persones', 'Analitzant moltes dades i detectant patrons', 'Anant a classe', 'Copiant altres màquines'], 1, '«Aprenen analitzant quantitats enormes de dades i detecten patrons.»'),
   ('Què opina la majoria dels experts?', ['Que pensen igual que nosaltres', 'Que no comprenen el món com els humans', 'Que mai no s’equivoquen', 'Que prompte aniran a l’escola'], 1, '«No tenen experiències ni una comprensió del món com la humana.»'),
   ('Quin problema s’hi esmenta?', ['Que són molt lentes', 'Que a vegades s’equivoquen amb tota seguretat', 'Que només funcionen en anglés', 'Que no es poden usar a casa'], 1, '«A vegades s’equivoquen amb tota seguretat.»'),
   ('Què recomana el text?', ['No utilitzar-les mai', 'Utilitzar-les amb esperit crític i comprovar la informació', 'Deixar que facen els deures', 'Creure tot el que diuen'], 1, '«Convé utilitzar-los amb esperit crític.»'),
   ('Quin tipus de text és?', ['Un conte fantàstic', 'Un text argumentatiu que convida a reflexionar', 'Una recepta', 'Un poema'], 1, 'Planteja una pregunta, aporta arguments i acaba amb una reflexió.')]),
 ('lectura_ca_l9_guernica', 9, 'Guernica: un crit pintat', '🖤', ['arte', 'historia'],
  'El 26 d’abril de 1937, en plena guerra civil espanyola, avions alemanys i italians, aliats de les tropes de Franco, van bombardejar la vila basca de Gernika. Era dia de mercat. La vila va quedar en gran part destruïda i van morir nombrosos civils; encara hui els historiadors debaten la xifra exacta.\n\nPablo Picasso vivia aleshores a París i havia rebut l’encàrrec de pintar un mural per al pavelló de la República espanyola en l’Exposició Internacional d’aquell any. Commocionat per les notícies, va decidir que la seua obra parlaria de l’horror d’aquell bombardeig. En poc més d’un mes va pintar un llenç de quasi huit metres d’amplària.\n\nEl Guernica no mostra avions ni explosions. En lloc d’això hi apareixen figures deformades: una mare que crida amb el seu fill mort en braços, un cavall ferit, un bou, una bombeta que pareix un ull. Picasso va triar només el blanc, el negre i els grisos, com en les fotografies dels periòdics.\n\nPer desig del pintor, el quadre no va viatjar a Espanya fins que es va recuperar la democràcia: hi va arribar l’any 1981. Hui es troba en el Museu Reina Sofia, a Madrid, i s’ha convertit en un símbol universal contra la guerra.',
  [('Què va passar el 26 d’abril de 1937?', ['Es va inaugurar un museu', 'Van bombardejar la vila de Gernika', 'Picasso va arribar a París', 'Es va acabar la guerra'], 1, '«Van bombardejar la vila basca de Gernika.»'),
   ('Per a quin lloc va pintar Picasso el quadre?', ['Per a la seua casa de París', 'Per al pavelló de la República en l’Exposició Internacional', 'Per a l’ajuntament de Gernika', 'Per al Museu del Prado'], 1, '«Un mural per al pavelló de la República espanyola en l’Exposició Internacional.»'),
   ('Amb què relaciona el text els colors del quadre?', ['Amb les fotografies dels periòdics', 'Amb la bandera d’Espanya', 'Amb la mar de nit', 'Amb els colors del mercat'], 0, '«Com en les fotografies dels periòdics.»'),
   ('Quan va arribar el Guernica a Espanya?', ['L’any 1937', 'L’any 1981', 'L’any 1992', 'L’any 2000'], 1, '«Hi va arribar l’any 1981.»'),
   ('Per què s’ha convertit en un símbol?', ['Perquè és el quadre més car', 'Perquè expressa l’horror de la guerra de manera universal', 'Perquè té molts colors', 'Perquè és molt xicotet'], 1, '«S’ha convertit en un símbol universal contra la guerra.»')]),
]
